import glob
import unittest

# Load the RobotPet class from the exercise file printed in the book.
for path in sorted(glob.glob("*.py")):
    source = open(path).read()
    if "class RobotPet" in source and "unittest" not in source:
        exec(compile(source, path, "exec"))
        break


class TestRobotPet(unittest.TestCase):
    def test_name_is_stored(self):
        pet = RobotPet("Bolt", 100, "happy")
        self.assertEqual(pet.name, "Bolt")

    def test_battery_is_stored(self):
        pet = RobotPet("Bolt", 100, "happy")
        self.assertEqual(pet.battery, 100)

    def test_mood_is_stored(self):
        pet = RobotPet("Bolt", 100, "happy")
        self.assertEqual(pet.mood, "happy")

    def test_show_talent(self):
        pet = RobotPet("Bolt", 100, "happy")
        self.assertEqual(pet.show_talent(), "performs a generic trick!")


if __name__ == "__main__":
    unittest.main(verbosity=2)

import os
import unittest

from robot_pet import RobotPet


def make_pet():
    try:
        return RobotPet("Robo")
    except TypeError:
        return RobotPet()


CLASS_HEADER = (
    "class TestRobotPet(unittest.TestCase):\n"
    "    def setUp(self):\n"
    "        self.pet = make_pet()\n"
)

HERE = os.path.dirname(os.path.abspath(__file__))
with open(os.path.join(HERE, "unit_tests_that_change_state.py")) as source:
    test_methods = source.read()

namespace = {"unittest": unittest, "make_pet": make_pet}
exec(CLASS_HEADER + test_methods, namespace)

TestRobotPet = namespace["TestRobotPet"]

if __name__ == "__main__":
    unittest.main(argv=["run_tests"], verbosity=2, exit=False)

"""Robot pets from Chapter 7, now with the new speak() feature."""


class RobotPet:
    def __init__(self, name, battery=100, mood="neutral"):
        self.name = name
        self.battery = battery
        self.mood = mood

    def speak(self):
        if self.battery < 20:
            return f"{self.name} needs to recharge."
        if self.mood == "happy":
            return f"{self.name} is happy to see you!"
        return f"Hello, I am {self.name}."


class RobotCat(RobotPet):
    def speak(self):
        if self.battery < 20:
            return f"{self.name} is too tired to purr."
        if self.mood == "happy":
            return f"Purr... {self.name} is a happy kitty!"
        return f"Meow! I am {self.name}."


class RobotBird(RobotPet):
    def speak(self):
        if self.battery < 20:
            return f"{self.name} says the battery is low."
        if self.mood == "happy":
            return f"{self.name} sings: what a lovely day!"
        return f"Chirp chirp! I am {self.name}."


class RobotDog(RobotPet):
    def speak(self):
        if self.battery < 20:
            return f"{self.name} needs a charge."
        if self.mood == "happy":
            return f"Best day ever! {self.name} is wagging its tail!"
        return f"Woof! I am {self.name}."
